/** Stores the session a sign-in returned, so later calls are authenticated. */
function adopt(session: ApiAuthSession): ApiAuthSession {
  setSession(session.accessToken, session.expiresIn, session.refreshToken);
  return session;
}

export const auth = {
  async register(input: {
    email: string;
    password: string;
    displayName?: string;
    timezone?: string;
    device: ApiDeviceInfo;
  }): Promise<ApiAuthSession> {
    return adopt(
      await request<ApiAuthSession>('/auth/register', {
        method: 'POST',
        anonymous: true,
        body: input,
        idempotencyKey: newIdempotencyKey(),
      }),
    );
  },

  /** Confirms an address with the token from the e-mailed link. */
  verifyEmail: (token: string): Promise<ApiUser> =>
    request<ApiUser>('/auth/verify-email', { method: 'POST', anonymous: true, body: { token } }),
  /** Sends the confirmation link again to the signed-in account. */
  resendVerification: (): Promise<void> => requestVoid('/auth/resend-verification', { method: 'POST' }),
  /** Asks for a reset link; the server answers the same way for any address. */
  forgotPassword: (email: string): Promise<void> =>
    requestVoid('/auth/forgot-password', { method: 'POST', anonymous: true, body: { email } }),
  /** Sets a new password with the token from the e-mailed link. */
  resetPassword: (token: string, password: string): Promise<void> =>
    requestVoid('/auth/reset-password', { method: 'POST', anonymous: true, body: { token, password } }),
  async login(input: { email: string; password: string; device: ApiDeviceInfo }): Promise<ApiAuthSession> {
    return adopt(
      await request<ApiAuthSession>('/auth/login', { method: 'POST', anonymous: true, body: input }),
    );
  },

  async google(input: ApiGoogleAuthRequest): Promise<ApiAuthSession> {
    return adopt(
      await request<ApiAuthSession>('/auth/google', { method: 'POST', anonymous: true, body: input }),
    );
  },

  async apple(input: ApiAppleAuthRequest): Promise<ApiAuthSession> {
    return adopt(
      await request<ApiAuthSession>('/auth/apple', { method: 'POST', anonymous: true, body: input }),
    );
  },

  /**
   * Spends the ticket a sign-in got for an account in its deletion grace:
   * restores the account and opens the session that sign-in asked for.
   */
  async restoreDeleted(ticket: string, device: ApiDeviceInfo): Promise<ApiAuthSession> {
    return adopt(
      await request<ApiAuthSession>('/auth/pending-deletion/restore', {
        method: 'POST',
        anonymous: true,
        body: { ticket, device },
      }),
    );
  },
  /**
   * Spends that ticket the other way: the old account stays deleted (and is
   * erased on its date) and the same sign-in opens a new account.
   */
  async startNewAccount(ticket: string, device: ApiDeviceInfo): Promise<ApiAuthSession> {
    return adopt(
      await request<ApiAuthSession>('/auth/pending-deletion/start-new', {
        method: 'POST',
        anonymous: true,
        body: { ticket, device },
      }),
    );
  },

  async logout(): Promise<void> {
    await requestVoid('/auth/logout', { method: 'POST' });
  },
  /**
   * Gives a password to an account that signs in only through Google or
   * Apple. The provider keeps working; this adds a second way in.
   */
  setPassword: (password: string): Promise<void> =>
    requestVoid('/auth/set-password', { method: 'POST', body: { password } }),

  changePassword: (currentPassword: string, newPassword: string): Promise<void> =>
    requestVoid('/auth/change-password', { method: 'POST', body: { currentPassword, newPassword } }),

  /**
   * Proves the password again for the session in use. The answer is a
   * fresher access token for the same session, which replaces the current
   * one; the refresh token is untouched.
   */
  async reauth(password: string): Promise<void> {
    const fresh = await request<{ accessToken: string; expiresIn: number }>('/auth/reauth', {
      method: 'POST',
      body: { password },
    });
    setSession(fresh.accessToken, fresh.expiresIn);
  },
};

/**
 * The footer link of an e-mail (`/unsubscribe?token=…&c=…`). None of these
 * takes a session, on purpose: somebody who cannot sign in must still be able
 * to stop the e-mails, so the signed token in the link is the whole of it.
 */
export const email = {
  /**
   * Turns off one category for the account the link names, or all three
   * when none is given (what the single link in older e-mails promised).
   * Following the same link twice is not an error.
   */
  unsubscribe: (token: string, category?: ApiEmailCategory): Promise<void> =>
    requestVoid('/email/unsubscribe', {
      method: 'POST',
      anonymous: true,
      body: category === undefined ? { token } : { token, category },
    }),
  /** The account's three switches, read with the link's token. A POST so the token stays out of a URL. */
  preferences: (token: string): Promise<ApiEmailPreferences> =>
    request<ApiEmailPreferences>('/email/preferences/lookup', {
      method: 'POST',
      anonymous: true,
      body: { token },
    }),
  /** Sets the switches that are present and leaves the rest; answers with all three. */
  setPreferences: (input: ApiEmailPreferencesUpdate): Promise<ApiEmailPreferences> =>
    request<ApiEmailPreferences>('/email/preferences', { method: 'PUT', anonymous: true, body: input }),
};

export const me = {
  get: (): Promise<ApiUser> => request<ApiUser>('/me'),
  /**
   * Adds Google or Apple as a way into this account, with what the provider
   * has just issued. Needs a recent sign-in (403 reauth_required).
   */
  linkIdentity: (
    provider: ApiLinkableProvider,
    proof: ApiLinkIdentityRequest,
  ): Promise<ApiIdentityLinkResult> =>
    request<ApiIdentityLinkResult>(`/me/identities/${provider}`, { method: 'POST', body: proof }),
  /** Stops signing in with Google or Apple; never the last way in. */
  unlinkIdentity: (provider: ApiLinkableProvider): Promise<ApiIdentityLinkResult> =>
    request<ApiIdentityLinkResult>(`/me/identities/${provider}`, { method: 'DELETE' }),
  /**
   * A single-use ticket that hands this brand-new, empty account's sign-in
   * to an account the learner already has.
   */
  startIdentityTransfer: (provider: ApiLinkableProvider): Promise<ApiIdentityTransferTicket> =>
    request<ApiIdentityTransferTicket>('/me/identity-transfers', { method: 'POST', body: { provider } }),
  /** Spends that ticket from the account the learner already had. */
  claimIdentityTransfer: (ticket: string): Promise<ApiIdentityLinkResult> =>
    request<ApiIdentityLinkResult>('/me/identity-transfers/claim', { method: 'POST', body: { ticket } }),
  update: (input: ApiUserUpdate): Promise<ApiUser> =>
    request<ApiUser>('/me', { method: 'PATCH', body: input, idempotencyKey: newIdempotencyKey() }),
  /**
   * Deletes the account. The optional answer to "Why are you leaving?" rides
   * along; the server stores it after the deletion and never lets it stop it.
   */
  remove: (answer?: ApiAccountDeletionRequest): Promise<void> =>
    requestVoid('/me', answer === undefined ? { method: 'DELETE' } : { method: 'DELETE', body: answer }),
  sessions: (): Promise<ApiUserSession[]> =>
    request<{ sessions: ApiUserSession[] }>('/me/sessions').then((body) => body.sessions),
  revokeSession: (id: string): Promise<void> => requestVoid(`/me/sessions/${id}`, { method: 'DELETE' }),
  /**
   * Opens a session for another client of this account, such as the browser
   * extension, and returns its tokens; the refresh token comes in the body.
   */
  connectClient: (device: ApiDeviceInfo): Promise<ApiAuthSession> =>
    request<ApiAuthSession>('/me/sessions', {
      method: 'POST',
      body: { device },
      idempotencyKey: newIdempotencyKey(),
    }),
  /**
   * A one-time code for the desktop app, bound to its PKCE challenge and its
   * loopback address. The app trades it for its own session; this page never
   * sees the app's tokens.
   */
  createDesktopCode: (input: ApiDesktopCodeRequest): Promise<ApiDesktopCode> =>
    request<ApiDesktopCode>('/me/desktop-codes', { method: 'POST', body: input }),
  /**
   * A one-time code for the browser extension, bound to its PKCE challenge
   * and its identity redirect. The extension trades it for its own session;
   * this page never sees the extension's tokens.
   */
  createExtensionCode: (input: ApiExtensionCodeRequest): Promise<ApiExtensionCode> =>
    request<ApiExtensionCode>('/me/extension-codes', { method: 'POST', body: input }),
  /** Every Lexpad surface and what this account has done with it ("Lexpad everywhere"). */
  surfaces: (): Promise<ApiSurfaceStatus[]> =>
    request<{ surfaces: ApiSurfaceStatus[] }>('/me/surfaces').then((body) => body.surfaces),
  /** Which SRS v2 features this account and client may use (404 on a server without them). */
  srs: (): Promise<ApiSrsState> => request<ApiSrsState>('/me/srs'),
  /** "Remembered when due" per notebook over the last `days` days, and what personal tuning last found. */
  srsStats: (days: number): Promise<ApiSrsStats> =>
    request<ApiSrsStats>(`/me/srs/stats?days=${String(days)}`),
  /** Celebration moments any device of this account has had (newest first). */
  celebrations: (): Promise<ApiCelebrationKey[]> =>
    request<{ keys: ApiCelebrationKey[] }>('/me/celebrations').then((body) => body.keys),
  /**
   * Claims celebration moments: answers the keys this call won. Each key is
   * won by one device of the account only. `idempotencyKey` makes a retry
   * replay the first answer rather than read as lost.
   */
  claimCelebrations: (
    keys: readonly ApiCelebrationKey[],
    idempotencyKey: string,
  ): Promise<ApiCelebrationKey[]> =>
    request<{ won: ApiCelebrationKey[] }>('/me/celebrations/claim', {
      method: 'POST',
      body: { keys: [...keys] },
      idempotencyKey,
    }).then((body) => body.won),
  /**
   * Sends a note from Settings → Send feedback. The key is the note's own,
   * made once when the learner pressed Send, so a retry from the outbox is
   * stored once. Not retried by the client: the outbox keeps it.
   */
  sendFeedback: (
    input: ApiFeedbackInput,
    idempotencyKey: string,
    send: SyncSend = {},
  ): Promise<ApiFeedbackReceipt> =>
    request<ApiFeedbackReceipt>('/me/feedback', {
      method: 'POST',
      body: input,
      idempotencyKey,
      ...syncSend(send),
    }),
  /**
   * Settings → Invite friends: the caller's own invitation link, made the
   * first time it is asked for, and how many friends joined and earned Pro.
   */
  referral: (via?: ApiReferralVia): Promise<ApiReferralView> =>
    request<ApiReferralView>(via === undefined ? '/me/referral' : `/me/referral?via=${via}`),
  /**
   * Says where a new account came from (a source word or a friend's
   * invitation), once, right after signing up. The server answers 204
   * whatever happened, so there is nothing to read back.
   */
  attributeSignup: (input: ApiSignupAttribution, idempotencyKey: string): Promise<void> =>
    requestVoid('/me/referral/attribution', { method: 'POST', body: input, idempotencyKey }),
  /**
   * Keeps the introduction's answers (why, where words are met) with the
   * new account, once: the first answer stays and a repeat is a 204 too.
   */
  saveOnboardingAnswers: (input: ApiOnboardingAnswers, idempotencyKey: string): Promise<void> =>
    requestVoid('/me/onboarding', { method: 'PUT', body: input, idempotencyKey }),
  /**
   * Counts one visitor reaching one screen of the introduction (the data
   * plan, 22 Oct 2026). Needs no account and carries nothing about the
   * visitor; never retried, and the caller ignores every answer.
   */
  countIntroStep: (input: ApiIntroStepInput): Promise<void> =>
    requestVoid('/intro/steps', { method: 'POST', body: input, anonymous: true, retry: false }),
  /**
   * How an import this app ran itself ended: the kind of file, the outcome,
   * a short code and the row counts, never a file name or a word. Kept
   * without the account. Never retried; the caller ignores every answer.
   */
  reportImportOutcome: (input: ApiImportOutcomeInput): Promise<void> =>
    requestVoid('/me/import-outcomes', { method: 'POST', body: input, retry: false }),
  /**
   * The original file of an import this app ran itself that did not work
   * as expected, handed over once while the server keeps such files for a
   * day so its team can fix it (`ClientConfig.importFileCapture`). Never retried; the
   * caller ignores every answer, a 404 from an older server included.
   */
  keepImportFile: (file: Blob, filename: string, outcome: ApiImportOutcomeInput): Promise<void> => {
    const form = new FormData();
    form.set('kind', outcome.kind);
    form.set('outcome', outcome.outcome);
    if (outcome.errorCode !== undefined) form.set('errorCode', outcome.errorCode);
    // The server keeps a "done" import's file only when rows were skipped.
    if (outcome.rowsSkipped !== undefined) form.set('rowsSkipped', String(outcome.rowsSkipped));
    form.set('file', file, filename);
    return requestVoid('/me/import-files', { method: 'POST', raw: form, retry: false });
  },
  /** The cards on Today that suggest another surface: the rules and this account's history. */
  nudges: (): Promise<ApiNudgeView> => request<ApiNudgeView>('/me/nudges'),
  /** Records what happened to one card in this app session; repeating it is a no-op. */
  recordNudge: (id: ApiNudgeId, event: ApiNudgeEvent, session: string): Promise<ApiNudgeView> =>
    request<ApiNudgeView>(`/me/nudges/${id}`, {
      method: 'PUT',
      body: { event, session },
      idempotencyKey: newIdempotencyKey(),
    }),
  requestExport: (): Promise<ApiExportJob> => request<ApiExportJob>('/me/export'),
  exportStatus: (jobId: string): Promise<ApiExportJob> => request<ApiExportJob>(`/me/export/${jobId}`),
  downloadExport: (jobId: string): Promise<Blob> =>
    request<Blob>(`/me/export/${jobId}/download`, { expect: 'blob' }),
};

