export const sync = {
  snapshot: (): Promise<ApiSyncSnapshot> =>
    request<ApiSyncSnapshot>('/sync/snapshot', { signal: AbortSignal.timeout(SNAPSHOT_TIMEOUT_MS) }),
  pull: (since: string, limit?: number): Promise<ApiSyncPullResponse> =>
    request<ApiSyncPullResponse>('/sync/pull', {
      query: { since, limit },
      signal: AbortSignal.timeout(SYNC_REQUEST_TIMEOUT_MS),
      retry: false,
    }),
  push: (items: ApiSyncPushItem[], send: SyncSend = {}): Promise<ApiSyncPushResponse> =>
    request<ApiSyncPushResponse>('/sync/push', {
      method: 'POST',
      body: { items },
      signal: AbortSignal.timeout(SYNC_REQUEST_TIMEOUT_MS),
      ...syncSend(send),
    }),
};

export const ai = {
  /**
   * Asks for cards. `partial` ("Many at once") fills what today's allowance
   * has left instead of refusing the whole list: the answer's `plainWords`
   * are the rest, for the app to save as plain words. Without it the request
   * is all or nothing, which is what one word wants.
   */
  createCards: (
    notebookId: string,
    wordList: string[],
    hint?: string,
    options: { partial?: boolean } = {},
  ): Promise<ApiAiJob> =>
    withAiConsent(() =>
      request<ApiAiJob>('/ai/cards', {
        method: 'POST',
        body: {
          notebookId,
          words: wordList,
          ...(hint === undefined || hint === '' ? {} : { hint }),
          ...(options.partial === true ? { partial: true } : {}),
        },
        idempotencyKey: newIdempotencyKey(),
      }),
    ),
  job: (jobId: string): Promise<ApiAiJob> => request<ApiAiJob>(`/ai/jobs/${jobId}`),
  /**
   * Reports something a model wrote. The caller keeps the key across a
   * retry of the same report, so a second tap after a lost answer is stored
   * once.
   */
  report: (input: ApiAiReportInput, idempotencyKey: string): Promise<ApiAiReportReceipt> =>
    request<ApiAiReportReceipt>('/ai/reports', { method: 'POST', body: input, idempotencyKey }),
};

/**
 * What this account is on, and what it may buy. Everything about money goes
 * through here; nothing in the app decides for itself whether someone has
 * paid, and the plan is never stored locally.
 */
export const billing = {
  /** The plan, with campaign words in the UI `locale` (en when absent). */
  state: (locale?: string): Promise<ApiBillingState> =>
    request<ApiBillingState>('/billing/state', locale === undefined ? {} : { query: { locale } }),

  /**
   * Starts the Pro trial for an account that signed up without one. Closed
   * (404) until the server opens it to existing accounts; 409 `trial_used`
   * for an account that has had any Pro. No card and no charge.
   */
  startTrial: (): Promise<ApiTrial> =>
    request<ApiTrial>('/billing/trial', { method: 'POST', idempotencyKey: newIdempotencyKey() }),

  /**
   * Asks the server to open a checkout. It takes no money: it hands back the
   * token, the price and the account to carry, and Paddle does the rest. The
   * plan is granted only when Paddle tells the server so, which is why
   * nothing here reports success.
   */
  checkout: (
    plan: 'pro_monthly' | 'pro_yearly',
    extra: { offerId?: string | undefined; appTransactionId?: string | undefined } = {},
  ): Promise<ApiCheckout> =>
    request<ApiCheckout>('/billing/checkout', {
      method: 'POST',
      body: {
        plan,
        ...(extra.offerId === undefined ? {} : { offerId: extra.offerId }),
        ...(extra.appTransactionId === undefined ? {} : { appTransactionId: extra.appTransactionId }),
      },
    }),

  /**
   * What Pro did for the learner during the trial (running or ended), from
   * the account's own tables. 404 for an account that never had a trial.
   */
  trialFacts: (): Promise<ApiTrialFacts> => request<ApiTrialFacts>('/billing/trial/facts'),

  /**
   * "Don't remind me" (remind: false), or reminders back on. Stops every
   * pushed reminder about the trial and its offer, on every device; the
   * Plan page stays.
   */
  setOfferReminders: (remind: boolean): Promise<ApiOfferReminders> =>
    request<ApiOfferReminders>('/billing/reminders', {
      method: 'PUT',
      body: { remind },
      idempotencyKey: newIdempotencyKey(),
    }),

  /**
   * A moment the learner caused (the day's AI cards used up, a Pro feature
   * tapped, the Plan page opened, the card after a milestone). The server
   * may give a personal price here, once per account ever, and answers the
   * whole plan, with the offer when there is one. Never called in the
   * iPhone app (the server refuses it there with 403 `moment_not_here`).
   */
  moment: (kind: ApiMomentKind, locale?: string): Promise<ApiBillingMoment> =>
    request<ApiBillingMoment>('/billing/moment', {
      method: 'POST',
      body: { kind },
      idempotencyKey: newIdempotencyKey(),
      ...(locale === undefined ? {} : { query: { locale } }),
    }),

  /**
   * For the offer's funnel only (shown, opened, dismissed), counted at most
   * once a day per surface by the server. Fire and forget.
   */
  offerEvent: (offerId: string, event: ApiOfferEventInput): Promise<void> =>
    requestVoid(`/billing/offers/${encodeURIComponent(offerId)}/events`, { method: 'POST', body: event }),

  /**
   * Says why a purchase failed inside the app before the server heard of it
   * (StoreKit, Google Play, the shell), so the failure shows in the server's
   * log rather than only as "Something went wrong" on somebody's phone.
   * Codes and the store's error text only; nothing personal. Fire and forget.
   */
  reportPurchaseProblem: (problem: ApiPurchaseProblem): Promise<void> =>
    requestVoid('/billing/purchase-problems', { method: 'POST', body: problem }),

  /**
   * A short-lived link to the provider's own page for cancelling, changing a
   * card or downloading an invoice. Cancelling is theirs to handle: they are
   * the seller of record and the contract is with them.
   */
  portal: (): Promise<ApiBillingPortal> => request<ApiBillingPortal>('/billing/portal', { method: 'POST' }),
  /**
   * Why a cancelled plan was cancelled: one reason, asked once. The server
   * keeps it only for a cancelled paid plan and answers 204 either way.
   */
  /**
   * One step of the Pro offer at one place (the data plan's paywall funnel):
   * kept once a day per account, place and step. Never retried; the caller
   * ignores every answer.
   */
  paywallEvent: (input: ApiPaywallEventInput): Promise<void> =>
    requestVoid('/billing/paywall-events', { method: 'POST', body: input, retry: false }),
  cancelReason: (reason: ApiCancelReason): Promise<void> =>
    requestVoid('/billing/cancel-reason', { method: 'POST', body: { reason }, retry: false }),

  /**
   * Turns a Google Play purchase into a plan. The app sends the token Play
   * gave it and nothing else: the server reads the purchase back from
   * Google, so what was bought, when it ends and whose it is all come from
   * there. The answer is the plan, exactly as `state` would report it.
   */
  verifyGooglePurchase: (purchaseToken: string): Promise<ApiBillingState> =>
    request<ApiBillingState>('/billing/google/verify', { method: 'POST', body: { purchaseToken } }),

  /**
   * Turns an App Store purchase into a plan. The iPhone app sends the
   * transaction's id and, as a hint, StoreKit's signed copy of it; neither
   * is believed, because the server reads the subscription back from Apple.
   * The answer is the plan, exactly as `state` would report it. A 403
   * `purchase_not_yours` is a purchase made for another Lexpad account; 404
   * means the iPhone app is not selling; 503 is Apple out of reach.
   */
  verifyApplePurchase: (purchase: ApiApplePurchase): Promise<ApiBillingState> =>
    request<ApiBillingState>('/billing/apple/verify', {
      method: 'POST',
      body: {
        transactionId: purchase.transactionId,
        ...(purchase.signedTransaction === undefined
          ? {}
          : { signedTransaction: purchase.signedTransaction }),
      },
    }),
};

/**
 * Sharing a notebook, and opening one somebody shared.
 *
 * `open` is the one call in this file that needs no session: it is how a
 * link reaches somebody who has never used Lexpad, which is the whole point
 * of a link.
 */
export const share = {
  start: (notebookId: string): Promise<ApiShareLink> =>
    request<ApiShareLink>(`/notebooks/${notebookId}/share`, { method: 'POST' }),
  stop: (notebookId: string): Promise<void> =>
    requestVoid(`/notebooks/${notebookId}/share`, { method: 'DELETE' }),
  open: (shareId: string): Promise<ApiSharedNotebook> =>
    request<ApiSharedNotebook>(`/s/${shareId}`, { anonymous: true }),
  /**
   * "Add to my notebook": a shared notebook's words into one of the
   * learner's own with the same two languages, on every plan, because no
   * notebook is made. Words it already has are skipped. 409
   * `languages_differ` when the pairs do not match.
   */
  addTo: (notebookId: string, shareId: string): Promise<ApiSharedImportResult> =>
    request<ApiSharedImportResult>(`/notebooks/${notebookId}/import-shared`, {
      method: 'POST',
      body: { shareId },
      idempotencyKey: newIdempotencyKey(),
    }),
  copy: (shareId: string, title?: string): Promise<ApiNotebook> =>
    request<ApiNotebook>('/notebooks/import-shared', {
      method: 'POST',
      body: title === undefined ? { shareId } : { shareId, title },
      idempotencyKey: newIdempotencyKey(),
    }),
};

/**
 * Promotion codes.
 *
 * `look` needs no session, like opening a shared notebook: a promotion link
 * is followed by people who have not signed in yet, and a page that cannot
 * say what it is offering is not worth opening.
 */
/**
 * Reading a text the learner has just read.
 *
 * Synchronous, unlike card generation: one paragraph is one short call and
 * the answer is a list somebody is waiting to look at, so there is nothing
 * to poll.
 */
/**
 * The numbers a client needs to draw itself, read from the server because
 * a cap written into a bundle takes three app releases to change.
 */
export const config = {
  get: (): Promise<ApiClientConfig> => request<ApiClientConfig>('/config'),
};

export const read = {
  text: (notebookId: string, text: string): Promise<ApiWorthKeeping> =>
    withAiConsent(() =>
      request<ApiWorthKeeping>('/ai/read', {
        method: 'POST',
        body: { notebookId, text },
        idempotencyKey: newIdempotencyKey(),
      }),
    ),
};

/**
 * Practice modes that need the server (SRS v2 phase E). Use it in a sentence
 * is a model call while somebody waits, so it carries its own timeout: a
 * slow model must end in "try again", not a frozen screen.
 */
export const modes = {
  judgeSentence: (wordId: string, sentence: string, signal?: AbortSignal): Promise<ApiSentenceFeedback> =>
    withAiConsent(() =>
      request<ApiSentenceFeedback>('/ai/sentence-feedback', {
        method: 'POST',
        body: { wordId, sentence },
        idempotencyKey: newIdempotencyKey(),
        ...(signal === undefined ? {} : { signal }),
      }),
    ),
  /** Turns streak freeze on or off; answers the streak as the server keeps it. */
  setStreakFreeze: (on: boolean): Promise<ApiStreak> =>
    request<ApiStreak>('/me/streak-freeze', {
      method: 'PUT',
      body: { on },
      idempotencyKey: newIdempotencyKey(),
    }),
};

export const promo = {
  look: (code: string): Promise<ApiPromoOffer> =>
    request<ApiPromoOffer>(`/promo/${encodeURIComponent(code)}`, { anonymous: true }),
  redeem: (code: string): Promise<ApiPromoRedeemed> =>
    request<ApiPromoRedeemed>('/promo/redeem', {
      method: 'POST',
      body: { code },
      idempotencyKey: newIdempotencyKey(),
    }),
};

export const devices = {
  register: (input: ApiDeviceRegistration): Promise<void> =>
    requestVoid('/devices', { method: 'POST', body: input }),
  /**
   * Forgets this install's push token, so a phone handed to somebody else
   * stops receiving the previous owner's notifications. Safe to repeat.
   */
  unregister: (deviceId: string): Promise<void> =>
    requestVoid(`/devices/${encodeURIComponent(deviceId)}`, { method: 'DELETE' }),
};

/**
 * The bell on Today: what the server has said to this account. Announcements,
 * gifts and come-back notes land here whether or not a phone or browser
 * showed them as a pop-up.
 */
export const inbox = {
  list: (query: { cursor?: string; limit?: number } = {}): Promise<ApiNotificationPage> =>
    request<ApiNotificationPage>('/notifications', { query }),
  /** Marks those ids read; with none, everything the account has. */
  markRead: (ids?: string[]): Promise<void> =>
    requestVoid('/notifications/read', { method: 'POST', body: ids === undefined ? {} : { ids } }),
};

/**
 * A short form an operator sent with a notification. Only an account whose
 * inbox holds that notification may read or answer it (404 otherwise, the
 * same as an id that does not exist), and each account answers once.
 * Answering repeats its Idempotency-Key when a send is tried again.
 */
export const forms = {
  get: (formId: string): Promise<ApiForm> => request<ApiForm>(`/forms/${encodeURIComponent(formId)}`),
  answer: (
    formId: string,
    input: ApiFormAnswerInput,
    idempotencyKey: string,
  ): Promise<ApiFormAnswerReceipt> =>
    request<ApiFormAnswerReceipt>(`/forms/${encodeURIComponent(formId)}/answers`, {
      method: 'POST',
      body: input,
      idempotencyKey,
    }),
};

/**
 * Chat assistants (ChatGPT, Claude) connected over OAuth and MCP. The OAuth
 * endpoints themselves live outside this API; these are the consent screen's
 * two calls and the Settings list. Ids are opaque and path-encoded.
 *
 * The consent calls depend on `credentials: 'include'` (every request sends
 * it): /oauth/authorize set an HttpOnly cookie on the API host binding the
 * request to this browser, and without it the API answers 404 as for an
 * expired request.
 */
export const connections = {
  request: (id: string): Promise<ApiAuthorizationRequest> =>
    request<ApiAuthorizationRequest>(`/oauth/requests/${encodeURIComponent(id)}`),
  decide: (id: string, allow: boolean): Promise<ApiAuthorizationRedirect> =>
    request<ApiAuthorizationRedirect>(`/oauth/requests/${encodeURIComponent(id)}/decision`, {
      method: 'POST',
      body: { allow },
    }),
  list: (): Promise<ApiConnection[]> => request<ApiConnection[]>('/me/connections'),
  revoke: (id: string): Promise<void> =>
    requestVoid(`/me/connections/${encodeURIComponent(id)}`, { method: 'DELETE' }),
};

/**
 * Lex: the assistant a learner asks about their own words.
 *
 * Asking is two steps on purpose. `ask` returns as soon as both messages
 * exist, so the screen has somewhere to render into before a token has been
 * produced; `listen` then follows the answer as it is written. They are
 * separate calls because the answer outlives the request that asked for it:
 * locking a phone mid-answer does not throw it away, and coming back
 * resumes from where the reading stopped rather than from the beginning.
 */
export const lex = {
  conversations: (
    cursor?: string,
    limit?: number,
  ): Promise<{ items: ApiLexConversation[]; nextCursor?: string }> =>
    request('/lex/conversations', { query: { cursor, limit } }),

  start: (notebookId?: string): Promise<ApiLexConversation> =>
    request('/lex/conversations', {
      method: 'POST',
      body: { notebookId },
      idempotencyKey: newIdempotencyKey(),
    }),

  conversation: (id: string): Promise<{ conversation: ApiLexConversation; messages: ApiLexMessage[] }> =>
    request(`/lex/conversations/${id}`),

  remove: (id: string): Promise<void> => requestVoid(`/lex/conversations/${id}`, { method: 'DELETE' }),

  ask: (id: string, text: string): Promise<{ question: ApiLexMessage; answer: ApiLexMessage }> =>
    withAiConsent(() =>
      request<{ question: ApiLexMessage; answer: ApiLexMessage }>(`/lex/conversations/${id}/messages`, {
        method: 'POST',
        body: { text },
        idempotencyKey: newIdempotencyKey(),
      }),
    ),

  regenerate: (messageId: string): Promise<ApiLexMessage> =>
    withAiConsent(() =>
      request<ApiLexMessage>(`/lex/messages/${messageId}/regenerate`, {
        method: 'POST',
        idempotencyKey: newIdempotencyKey(),
      }),
    ),

  rate: (messageId: string, feedback: ApiLexFeedback): Promise<void> =>
    requestVoid(`/lex/messages/${messageId}/feedback`, { method: 'PUT', body: feedback }),

  unrate: (messageId: string): Promise<void> =>
    requestVoid(`/lex/messages/${messageId}/feedback`, { method: 'DELETE' }),

  /**
   * Records what the learner did with a change Lex proposed. The change
   * itself was made on this device and goes through sync like any edit;
   * this only stops the card coming back.
   */
  decide: (messageId: string, actionId: string, state: ApiLexActionDecision): Promise<void> =>
    requestVoid(`/lex/messages/${messageId}/actions/${encodeURIComponent(actionId)}`, {
      method: 'PUT',
      body: { state },
    }),

  /**
   * Follows an answer as it is written. `after` is the last event id the
   * reader saw, so a stream picked up again sends only what was missed.
   */
  listen: (
    messageId: string,
    handlers: {
      onToken: (text: string, id: string) => void;
      onDone: () => void;
      onError: (reason: string) => void;
      /** The changes the answer proposes, sent once before it is done. */
      onActions?: (actions: ApiLexAction[]) => void;
    },
    options: { after?: string; signal?: AbortSignal } = {},
  ): Promise<void> =>
    stream(`/lex/messages/${messageId}/stream`, {
      ...(options.after !== undefined ? { lastEventId: options.after } : {}),
      ...(options.signal ? { signal: options.signal } : {}),
      onEvent: (e: ServerEvent) => {
        if (e.event === 'token') {
          const payload = JSON.parse(e.data) as { t?: string };
          if (typeof payload.t === 'string') handlers.onToken(payload.t, e.id);
        } else if (e.event === 'actions') {
          const payload = JSON.parse(e.data) as { actions?: ApiLexAction[] };
          if (Array.isArray(payload.actions)) handlers.onActions?.(payload.actions);
        } else if (e.event === 'done') {
          handlers.onDone();
        } else if (e.event === 'error') {
          const payload = JSON.parse(e.data) as { reason?: string };
          handlers.onError(payload.reason ?? '');
        }
      },
    }),
};
